package com.waypoint.planning.entity;
import jakarta.persistence.*;import org.hibernate.annotations.JdbcTypeCode;import org.hibernate.type.SqlTypes;import java.time.*;import java.util.*;
@Entity @Table(name="allocations",schema="public") public class AllocationEntity {
 @Id @GeneratedValue(strategy=GenerationType.UUID) @Column(name="allocation_id") private UUID id; @Column(name="order_id",nullable=false) private UUID orderId; @Column(name="trip_id") private UUID tripId; @Column(name="vehicle_id") private String vehicleId; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="allocation_status") private AllocationStatus status; @Column(name="stop_index") private Integer stopIndex; @Column(name="planned_arrival") private LocalTime plannedArrival; @Column(name="deferral_reason") private String deferralReason; @Column(name="failed_constraint",insertable=false,updatable=false) private String failedConstraint; @Column(name="retry_date") private LocalDate retryDate; @Column(name="allocated_by",nullable=false) private String allocatedBy;
 protected AllocationEntity(){} public AllocationEntity(UUID orderId,UUID tripId,String by){this.orderId=orderId;this.tripId=tripId;allocatedBy=by==null?"SYSTEM":by;status=AllocationStatus.TENTATIVE;}
 public static AllocationEntity deferred(UUID orderId,String reason,LocalDate nextDate,String by){AllocationEntity a=new AllocationEntity();a.orderId=orderId;a.status=AllocationStatus.DEFERRED;a.deferralReason=reason;a.retryDate=nextDate;a.allocatedBy=by==null?"SYSTEM":by;return a;}
 public UUID getId(){return id;} public UUID getOrderId(){return orderId;} public UUID getTripId(){return tripId;} public AllocationStatus getStatus(){return status;} public String getVehicleId(){return vehicleId;} public LocalDate getRetryDate(){return retryDate;} public void changeRetryDate(LocalDate date){retryDate=date;} public void returnToPlanning(){status=AllocationStatus.RETURNED_TO_PLANNING;} public void assign(String vehicle){vehicleId=vehicle;} public void position(int index,LocalTime arrival){stopIndex=index;plannedArrival=arrival;} public void confirm(){status=AllocationStatus.ALLOCATED;}
}
